from functools import partial, wraps

def original():
    return "original"

@wraps(original)
def wrapped():
    return original()

partial_wrapped = partial(wrapped)

def unwrap_logic(call):
    while True:
        unwrapped = inspect.unwrap(call)
        if unwrapped != call:
            call = unwrapped
            continue
        if hasattr(call, "func"):
            call = call.func
            continue
        break
    return call

print(f"Original: {original}")
print(f"Unwrapped: {unwrap_logic(partial_wrapped)}")
print(f"Is same: {unwrap_logic(partial_wrapped) is original}")

